  form.dataset.bookingInitialized='yes';
  const select=form.querySelector('#vf-editing-package'),message=form.querySelector('#vf-editing-message'),phone=form.querySelector('#vf-editing-whatsapp'),date=form.querySelector('#vf-editing-date'),status=form.querySelector('#vf-editing-status');
  const now=new Date();
  date.min=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')+'-'+String(now.getDate()).padStart(2,'0');
  let country='255';
  try{country=({TZ:'255',KE:'254',UG:'256',RW:'250',US:'1',CA:'1',GB:'44',ZA:'27',NG:'234',GH:'233'})[new Intl.Locale(navigator.language).region]||country}catch(_){}
  if(!phone.value)phone.value='+'+country+' ';
