   if(bad){bad.setAttribute('aria-invalid','true');bad.focus();bad.reportValidity();status.classList.add('is-error');status.textContent='Please complete all required fields.';return}
   const whatsapp=phone.value.trim(),digits=whatsapp.replace(/\D/g,'');
